/* xx_ibmpack_extractor.c - search raw data for IBMPACK.
 *
 * Scans for:
 *   A5 96 FE FF at +0  ("....")
 *   A5 96 FF FF at +0  ("....")
 *   A5 96 14 0A at +0  ("....")
 *   A5 96 00 14 at +0  ("....")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the ibmpack reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/ibmpack/xx_ibmpack.h"

static const uint8_t k_anchor0[] = { 0xA5, 0x96, 0xFE, 0xFF };
static const uint8_t k_anchor1[] = { 0xA5, 0x96, 0xFF, 0xFF };
static const uint8_t k_anchor2[] = { 0xA5, 0x96, 0x14, 0x0A };
static const uint8_t k_anchor3[] = { 0xA5, 0x96, 0x00, 0x14 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
    { k_anchor1, sizeof(k_anchor1), 0U },
    { k_anchor2, sizeof(k_anchor2), 0U },
    { k_anchor3, sizeof(k_anchor3), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_IBMPACK };

static Abstractformat *xx_ibmpack_search_open(xx_io_device *window) {
    xx_ibmpack *reader = xx_ibmpack_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_ibmpack_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_ibmpack_free((xx_ibmpack *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_ibmpack_search_open, xx_ibmpack_search_close
};

static xx_format_search_state *xx_ibmpack_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_ibmpack_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_ibmpack_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_ibmpack_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_ibmpack_extractor = {
    xx_ibmpack_create_format_search,
    xx_ibmpack_get_current_format_info,
    xx_ibmpack_format_search_find_next,
    xx_ibmpack_free_format_search
};
